def preserve_manual_baseline(apps: Apps, schema_editor: BaseDatabaseSchemaEditor) -> None:
    Manual = apps.get_model("runtime", "ManualCondition")
    History = apps.get_model("runtime", "ManualConditionHistory")
    History.objects.using(schema_editor.connection.alias).bulk_create(
        [
            History(
                listing_id=row.listing_id,
                publication_order=0,
                choice=row.choice,
                revision=row.revision,
                confirmed_at=row.updated_at,
            )
            for row in Manual.objects.using(schema_editor.connection.alias).all()
        ]
    )


